/* Owner tools. Database functions and the server authorize every operation. */
window.KinnectAdmin=(()=>{
 let ctx,days=[],extras=[],bank=[],scheduled=[],recent=[],error='',notice='',working=false,ready=false,brief='',start='',loaded=false,team={can_manage:false,members:[]};
 const starter=[
 ['Your roommate wants to host tonight. You’re…','Inviting everyone','Putting on headphones'],
 ['You have one free elective. Pick one.','Something useful','Something completely new'],
 ['Is saving seats in a packed lecture fair?','Friends come first','First come, first served'],
 ['An unexpected free hour between classes.','Find a sunny spot','Get something done'],
 ['Your ideal study break?','A walk outside','A snack and a scroll'],
 ['The best plans happen…','Two weeks in advance','Twenty minutes before'],
 ['You’re picking a new club. What wins?','An interest I already love','Something I’ve never tried'],
 ['Your friend sends a five-minute voice memo.','Press play immediately','Can I get a summary?'],
 ['Would you share your class notes with a stranger?','Of course','Only if they ask nicely'],
 ['A whole day with no assignments.','Leave SLO for an adventure','Stay in and recharge'],
 ['Your group orders food. You…','Try everyone’s order','Stick to my own'],
 ['A good playlist should be…','All familiar favorites','Mostly new discoveries'],
 ['You spot someone you know across campus.','Shout their name','Wait for eye contact'],
 ['When you find a great new spot, you…','Tell the group chat','Keep it my secret'],
 ['Would you rather always pick the restaurant or the music?','The restaurant','The music'],
 ['Your backpack has…','Everything anyone could need','A laptop and good intentions'],
 ['A friend asks for honest outfit feedback.','The full truth','Gentle encouragement'],
 ['The lecture ends ten minutes early.','Best surprise ever','Finish the material, please'],
 ['You get to redesign your class schedule.','Three packed days','Five lighter days'],
 ['Someone brings a board game to the hangout.','I’m learning the rules','I’m starting the conversation'],
 ['When a movie ends, you…','Stay for the credits','Already heading out'],
 ['Your favorite part of a campus event?','Meeting someone new','Going with my friends'],
 ['A weekend with no plans feels…','Peaceful','Like a problem to solve'],
 ['Do friends need to like the same music?','It definitely helps','Different taste is better'],
 ['Your ideal group chat has…','A hundred messages a day','Only the essential updates'],
 ['Would you rather learn to surf or learn to DJ?','Surf','DJ'],
 ['A friend is late. Do you order first?','Yes, I’m hungry','Wait for them'],
 ['A perfect Sunday morning starts with…','An early adventure','Sleeping through it'],
 ['The best kind of gift?','Something thoughtful','An experience together'],
 ['Would you trade your phone for a free trip this weekend?','Where are we going?','My phone is coming too']
 ].map(([question_text,option_a,option_b])=>({question_text,option_a,option_b}));
 let liveRows=[],liveError='',liveDate='',liveUpdated='',liveBusy=false,liveTimer=null,liveRun=0;
 const clean=q=>({question_text:String(q.question_text||'').trim(),option_a:String(q.option_a||'').trim(),option_b:String(q.option_b||'').trim()});
 const blank=()=>({question_text:'',option_a:'',option_b:''});
 function shift(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
 function week(){days=Array.from({length:7},(_,i)=>{const date=shift(start,i);const existing=scheduled.filter(q=>q.question_date===date).sort((a,b)=>a.position-b.position);return {date,questions:existing.length===3?existing.map(clean):[blank(),blank(),blank()]}})}
 async function api(path,body){const r=await ctx.db.auth.getSession();if(r.error)throw r.error;const token=r.data.session?.access_token;if(!token)throw Error('Sign in again.');const response=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed.');return data}
 async function dashboard(){const r=await ctx.db.rpc('admin_question_dashboard');if(r.error)throw r.error;scheduled=r.data.scheduled||[];bank=r.data.backups||[];recent=r.data.recent||[];loaded=true;const access=await ctx.db.rpc('admin_team_access');team=access.error?{can_manage:false,members:[]}:access.data;}
 async function open(context){ctx=context;if(liveTimer)clearInterval(liveTimer);liveRun++;liveBusy=false;liveRows=[];liveError='';liveUpdated='';liveDate=ctx.dateKey();error='';notice='';try{await dashboard();start=ctx.dateKey(1);week();extras=[];await loadLiveResults();liveTimer=setInterval(()=>{if(!document.querySelector('#admin-live-results')){clearInterval(liveTimer);liveTimer=null;return}if(!document.hidden)loadLiveResults()},30000);try{ready=(await api('/api/admin/status')).ai_ready}catch(e){ready=false;notice=e.message}}catch(e){loaded=false;error=e.message||'Run the database setup to enable admin tools.'}}
 const E=v=>ctx.esc(v);
 function card(q,key){return `<article class="admin-question"><label>Question<input data-edit="${key}:question_text" value="${E(q.question_text)}" minlength="8" maxlength="180" required placeholder="A question worth talking about"></label><div class="admin-options"><label>Choice A<input data-edit="${key}:option_a" value="${E(q.option_a)}" maxlength="60" required></label><label>Choice B<input data-edit="${key}:option_b" value="${E(q.option_b)}" maxlength="60" required></label></div></article>`}

 function liveContents(){const heading=`<div class="admin-live-top"><div><span class="eyebrow">ADMIN ONLY · LIVE PREVIEW</span><h3>Today’s campus results.</h3><p class="fine">${E(liveDate)} · Updates every 30 seconds. Students see these results tomorrow.</p></div><button class="link-btn" id="admin-live-refresh" type="button" ${liveBusy?'disabled':''}>${liveBusy?'Refreshing…':'Refresh results'}</button></div>`;if(liveError)return heading+`<p class="error" role="alert">${E(liveError)}</p>`;if(!liveRows.length)return heading+'<p class="muted">No questions are scheduled for today.</p>';return heading+`<div class="result-grid">${liveRows.map((q,i)=>{const total=Number(q.votes_a)+Number(q.votes_b),a=total?Math.round(Number(q.votes_a)/total*100):0,b=total?100-a:0;return `<article class="card result"><span class="small-head muted">0${i+1}</span><h3>${E(q.question_text)}</h3>${total?`<div class="number">${q.my_choice===1?b:a}<span style="font-size:24px">%</span></div><p class="fine">${q.my_choice!==null?'chose your answer':`chose “${E(q.option_a)}”`}</p><div class="bar"><span style="width:${a}%"></span></div><div class="bar-legend"><span>${E(q.option_a)}<br>${a}% ${q.my_choice===0?'· YOU':''}</span><span>${E(q.option_b)}<br>${b}% ${q.my_choice===1?'· YOU':''}</span></div><p class="fine">${total} ${total===1?'response':'responses'}</p>`:'<p class="muted">No responses yet.</p>'}</article>`}).join('')}</div><p class="fine admin-live-stamp">${liveUpdated?'Updated '+E(liveUpdated)+'. ':''}Live totals may change as students answer. Viewing this does not change votes.</p>`}
 function bindLive(){document.querySelector('#admin-live-refresh')?.addEventListener('click',()=>loadLiveResults())}
 function paintLive(){const node=document.querySelector('#admin-live-results');if(node){node.innerHTML=liveContents();bindLive()}}
 async function loadLiveResults(){if(liveBusy)return;const run=liveRun;liveBusy=true;paintLive();try{const r=await ctx.db.rpc('admin_live_results');if(r.error)throw r.error;if(run!==liveRun)return;if(!r.data||!Array.isArray(r.data.questions))throw Error('Live results could not load. Try refreshing.');liveRows=r.data.questions;liveDate=r.data.date;liveUpdated=new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',second:'2-digit',timeZone:'America/Los_Angeles'});liveError=''}catch(e){if(run===liveRun){liveError=e.code==='PGRST202'?'Live results need the database update in supabase/05-admin-live-results.sql.':e.message||'Could not refresh live results.'}}finally{if(run===liveRun){liveBusy=false;paintLive()}}}
 function screen(){if(!ctx)return '<main class="page"><h2>Loading admin…</h2></main>';return `<main class="page admin-page"><button class="back" data-view="profile">← Profile</button><div class="admin-heading"><div><span class="eyebrow">KINNECT EDITOR</span><h2>A week of good questions.</h2><p class="muted">Review once. The daily mix takes care of itself.</p></div><span class="admin-badge">${bank.length} approved backups · ${Math.floor(bank.length/3)} days</span></div><div class="admin-status" role="status">${notice?E(notice):'Scheduled questions go live by date. An unscheduled day uses three unused, approved backups when the first student opens Kinnect.'}</div>${error?`<p class="error" role="alert">${E(error)}</p>`:''}${loaded?'<section id="admin-live-results" class="admin-live-panel" aria-label="Live campus results">'+liveContents()+'</section>':''}${!loaded?'<p class="notice">The database setup is required. Your current questions and student answers are unchanged.</p>':`<section class="admin-controls"><label>Week starting<input type="date" id="admin-start" min="${ctx.dateKey(1)}" max="${ctx.dateKey(84)}" value="${start}" ${working?'disabled':''}></label><label class="admin-brief">Editorial brief · optional<input id="admin-brief" maxlength="500" placeholder="More campus life, funny dilemmas, a few hot takes" value="${E(brief)}" ${working?'disabled':''}></label><button class="primary" id="admin-generate" ${working||!ready?'disabled':''}>${working?'Working…':'Generate a week with AI'}</button></section>${!ready?'<p class="fine">AI is not connected yet. You can write and schedule questions manually.</p>':''}<p class="fine">AI drafts are never published until you approve them. Generating replaces this unsaved draft.</p><details class="admin-import"><summary>Free option: import questions from ChatGPT</summary><p class="fine">Ask ChatGPT for 21 or 30 binary questions as a JSON array. Each item needs question_text, option_a, and option_b. Paste below: the first 21 fill the week; the rest become backup drafts.</p><label>Question JSON<textarea id="admin-import-text" rows="5" placeholder='[{"question_text":"Your question?","option_a":"Choice A","option_b":"Choice B"}]'></textarea></label><button class="link-btn" id="admin-import">Load draft</button><button class="link-btn" id="admin-prompt">Copy ChatGPT prompt</button></details><form id="admin-week-form"><fieldset ${working?'disabled':''} class="admin-fieldset">${days.map((day,d)=>`<section class="admin-day"><div class="admin-day-title"><h3>${E(new Date(day.date+'T12:00:00Z').toLocaleDateString('en-US',{timeZone:'UTC',weekday:'long',month:'short',day:'numeric'}))}</h3><span>Three questions</span></div><div class="admin-question-grid">${day.questions.map((q,i)=>card(q,`${d}:${i}`)).join('')}</div></section>`).join('')}<div class="admin-save"><p>Approve these 21 questions for the selected week.<br><span class="fine">Today’s questions and saved answers cannot be changed here.</span></p><button class="primary" type="submit">Approve & schedule week</button></div></fieldset></form><section class="admin-backups"><div class="admin-day-title"><div><h3>Backup bank</h3><p class="fine">${bank.length<21?'Low: aim for at least 21 approved backups.':'Ready to cover gaps in your schedule.'} Unused backups are never repeated.</p></div><button class="link-btn" id="admin-starter" ${working?'disabled':''}>Review starter backups</button></div>${extras.length?`<p class="fine">Review these drafts, select the ones you like, then add them to your bank.</p><form id="admin-backup-form"><fieldset class="admin-fieldset" ${working?'disabled':''}><div class="admin-question-grid">${extras.map((q,i)=>`<div><label class="check"><input type="checkbox" data-extra="${i}" ${q.selected?'checked':''}>Approve this backup</label>${card(q,`extra:${i}`)}</div>`).join('')}</div><button class="primary" type="submit">Add selected backups</button></fieldset></form>`:''}<details><summary>View ${bank.length} approved backups</summary><div class="admin-bank-list">${bank.map(q=>`<p><strong>${E(q.question_text)}</strong><br><span class="fine">${E(q.option_a)} / ${E(q.option_b)}</span></p>`).join('')||'<p>No backups yet. Review the starter questions or generate a draft.</p>'}</div></details></section><section class="admin-backups"><h3>Question editors</h3><p class="fine">Editors can generate and schedule questions. Only the owner can add editors.</p>${team.members.map(m=>`<p>${E(m.email)}${m.is_owner?' · Owner':' · Editor'}</p>`).join('')}${team.can_manage?`<form id="admin-team-form" class="admin-controls"><label class="admin-brief">Teammate’s Cal Poly email<input type="email" id="admin-team-email" required placeholder="teammate@calpoly.edu" ${working?'disabled':''}></label><button class="primary" ${working?'disabled':''}>Add editor</button></form>`:''}</section>`}</main>`}
 function validate(list){const seen=new Set();for(const raw of list){const q=clean(raw);if(q.question_text.length<8||q.question_text.length>180||!q.option_a||!q.option_b||q.option_a.length>60||q.option_b.length>60||q.option_a.toLowerCase()===q.option_b.toLowerCase())throw Error('Each question needs text and two different answer choices.');const t=q.question_text.toLowerCase();if(seen.has(t))throw Error('Remove repeated questions from this draft.');seen.add(t)}}
 async function task(fn){if(working)return;working=true;error='';notice='';ctx.render();try{await fn()}catch(e){error=e.message||'Could not save. Your draft is still here.'}finally{working=false;ctx.render()}}
 function bind(){if(!ctx)return;bindLive();document.querySelector('#admin-prompt')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText('Write 30 fresh binary-choice questions for Kinnect, a Cal Poly San Luis Obispo student social app. Return ONLY a JSON array of objects with question_text, option_a, option_b. The first 21 form seven balanced days (campus life, student personality, light debate), followed by nine backups. Keep questions under 180 characters and answers under 60. Funny, conversational, mildly spicy, inclusive. No correct answers or invented news.');ctx.toast('Prompt copied. Paste it into ChatGPT.')}catch{ctx.toast('Copy the JSON format shown above.')}});document.querySelector('#admin-import')?.addEventListener('click',()=>{try{const text=document.querySelector('#admin-import-text').value.trim().replace(/^```(?:json)?\s*|```$/g,'');let list=JSON.parse(text);if(!Array.isArray(list))list=list.questions;if(!Array.isArray(list)||![21,30].includes(list.length))throw Error('Paste exactly 21 or 30 questions.');validate(list);days=days.map((d,i)=>({...d,questions:list.slice(i*3,i*3+3).map(clean)}));extras=list.slice(21).map(q=>({...clean(q),selected:false}));notice='Imported draft ready. Review it, then approve the week.';error='';ctx.render()}catch(e){ctx.toast(e.message||'Could not read that JSON.')}});document.querySelector('#admin-team-form')?.addEventListener('submit',e=>{e.preventDefault();const email=document.querySelector('#admin-team-email').value.trim();task(async()=>{const r=await ctx.db.rpc('admin_add_question_editor',{p_email:email});if(r.error)throw r.error;await dashboard();notice='Editor added. They can refresh Kinnect and open Question admin from Profile.'})});document.querySelectorAll('[data-edit]').forEach(el=>el.addEventListener('input',()=>{const [d,i,key]=el.dataset.edit.split(':');(d==='extra'?extras[+i]:days[+d].questions[+i])[key]=el.value}));document.querySelectorAll('[data-extra]').forEach(el=>el.addEventListener('change',()=>extras[+el.dataset.extra].selected=el.checked));document.querySelector('#admin-brief')?.addEventListener('input',e=>brief=e.target.value);document.querySelector('#admin-start')?.addEventListener('change',e=>{if(e.target.value<ctx.dateKey(1)||e.target.value>ctx.dateKey(84))return;start=e.target.value;week();notice='Loaded the selected week. Existing questions appear where scheduled.';ctx.render()});document.querySelector('#admin-generate')?.addEventListener('click',()=>task(async()=>{const draft=await api('/api/admin/generate',{brief});if(!Array.isArray(draft.questions)||draft.questions.length!==30)throw Error('Incomplete AI draft. Try again.');days=days.map((d,i)=>({...d,questions:draft.questions.slice(i*3,i*3+3).map(clean)}));extras=draft.questions.slice(21).map(q=>({...clean(q),selected:false}));notice='Draft ready. Review all seven days before approving; nothing has been published.'}));document.querySelector('#admin-week-form')?.addEventListener('submit',e=>{e.preventDefault();task(async()=>{validate(days.flatMap(d=>d.questions));const r=await ctx.db.rpc('admin_save_question_plan',{p_days:days.map(d=>({date:d.date,questions:d.questions.map(clean)})),p_backups:[]});if(r.error)throw r.error;await dashboard();notice='Week approved. Each mix will appear automatically on its scheduled date.'})});document.querySelector('#admin-starter')?.addEventListener('click',()=>{const used=new Set([...recent,...bank.map(q=>q.question_text),...scheduled.map(q=>q.question_text)].map(t=>t.trim().toLowerCase()));extras=starter.filter(q=>!used.has(q.question_text.toLowerCase())).map(q=>({...q,selected:false}));notice='Starter drafts loaded. Select the questions you approve for your backup bank.';ctx.render()});document.querySelector('#admin-backup-form')?.addEventListener('submit',e=>{e.preventDefault();task(async()=>{const selected=extras.filter(q=>q.selected).map(clean);if(!selected.length)throw Error('Select at least one backup to approve.');validate(selected);const r=await ctx.db.rpc('admin_save_question_plan',{p_days:[],p_backups:selected});if(r.error)throw r.error;await dashboard();extras=extras.filter(q=>!q.selected);notice=`Added ${selected.length} approved backups. The bank now covers ${Math.floor(bank.length/3)} unscheduled days.`})})}
 return {open,screen,bind};
})();
